// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }
    function testFuzz_property(uint256 minSum, uint256 lockTime, uint256 collectAmt) public {
        vm.assume(minSum <= type(uint128).max);
        vm.assume(lockTime <= type(uint128).max);
        vm.assume(collectAmt <= type(uint128).max);

        c.Initialized();

        try c.SetMinSum(minSum) {
            assertTrue(false);
        } catch {
            assertEq(c.MinSum(), 0);
        }
    }
}
